<?php if($entity==='products'): ?><label for="name">Product name</label><input id="name" name="name" value="<?= $value('name') ?>" maxlength="100" required placeholder="e.g. iPhone 16 Pro"><div class="two-col"><div><label for="price">Price (₱)</label><input id="price" name="price" type="number" min="0.01" max="99999999.99" step="0.01" value="<?= $value('price') ?>" required></div><div><label for="stock_quantity">Stock quantity</label><input id="stock_quantity" name="stock_quantity" type="number" min="0" max="1000000" step="1" value="<?= $value('stock_quantity',0) ?>" required></div></div><label for="category">Category</label><select id="category" name="category"><?php foreach(['Phones','Tablets','Audio','Wearables','Laptops','Accessories'] as $cat): ?><option <?= ($values['category']??'')===$cat?'selected':'' ?>><?= $cat ?></option><?php endforeach ?></select>
<?php else: ?><label for="full_name">Full name</label><input id="full_name" name="full_name" maxlength="100" value="<?= $value('full_name') ?>" required><?php if($entity==='customers'): ?><label for="email">Email address</label><input id="email" name="email" type="email" maxlength="100" value="<?= $value('email') ?>" required><label for="phone">Phone <span class="muted">(optional)</span></label><input id="phone" name="phone" type="tel" maxlength="20" value="<?= $value('phone') ?>"><?php else: ?><label for="username">Username</label><input id="username" name="username" minlength="3" maxlength="50" pattern="[A-Za-z0-9_-]+" value="<?= $value('username') ?>" required autocomplete="off"><label for="password"><?= isset($row['id'])?'New password':'Password' ?></label><input id="password" name="password" type="password" minlength="12" maxlength="72" autocomplete="new-password" <?= isset($row['id'])?'':'required' ?>><small class="field-help">12–72 bytes. <?= isset($row['id'])?'Leave blank to keep the current password.':'' ?></small><?php endif ?><?php endif ?></div>
<?php if($entity!=='customers'): $field=$entity==='staff'?'avatar':'image'; ?><div class="upload-block"><label for="<?= $field ?>"><?= $entity==='staff'?'Staff avatar':'Product image' ?></label><div class="upload-preview"><?php if(!empty($row[$field])): ?><img id="image-preview" src="<?= base_url($row[$field]) ?>" alt="Current image"><?php else: ?><img id="image-preview" src="<?= base_url('assets/'.($entity==='staff'?'logo.svg':'devices/phone.svg')) ?>" alt="Image placeholder"><?php endif ?></div><input id="<?= $field ?>" name="<?= $field ?>" type="file" accept="image/jpeg,image/png,image/webp" data-image-input><small class="field-help">JPG, PNG or WebP · Up to 2 MB<br><?= $entity==='staff'?'Prepared as a 256 × 256 avatar.':'Resized to fit within 1000 × 1000 pixels.' ?></small></div><?php endif ?></div><div class="form-actions"><a class="btn secondary" href="<?= site_url($entity) ?>">Cancel</a><button class="btn primary" type="submit">Save <?= $entity==='staff'?'staff member':($entity==='products'?'product':'customer') ?> ↗</button></div></form>
<?php if(isset($row['id'])): ?><section class="danger-zone"><div><h3><?= $entity==='products'?'Archive product':'Delete record' ?></h3><p><?= $entity==='products'?'Remove this product from the active catalog. Sales history is retained.':($entity==='staff'?'Staff with recorded sales cannot be deleted.':'Past sales will show as walk-in after this customer is deleted.') ?></p></div><form method="post" action="<?= site_url($entity.'/'.$row['id'].'/delete') ?>" data-confirm="<?= $entity==='products'?'Archive this product?':'Delete this record? This cannot be undone.' ?>"><?= csrf_field() ?><button class="btn danger" type="submit"><?= $entity==='products'?'Archive':'Delete' ?></button></form></section><?php endif ?><?= $this->endSection() ?>
